<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>欧姆定律：电压、电阻与电流</title>
<style>
  :root{
    --bg:#0f1720;
    --fg:#e8eef4;
    --accent:#ffd166;
    --panel:#17222e;
    --muted:#9fb0c0;
    --grid:#26364a;
    --axis:#55708a;
    --wire:#7ee787;
    --res:#ff8fa3;
    --op:#4cc9f0;
    --hot:#ffb454;
  }
  *{box-sizing:border-box;}
  body{
    margin:0;padding:16px;
    background:var(--bg);color:var(--fg);
    font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,"PingFang SC","Microsoft YaHei",sans-serif;
    line-height:1.5;
  }
  .wrap{max-width:940px;margin:0 auto;}
  h1{font-size:1.15rem;margin:0 0 4px;font-weight:650;}
  .sub{color:var(--muted);font-size:.85rem;margin:0 0 14px;}
  .eq{
    background:var(--panel);border:1px solid var(--grid);border-radius:10px;
    padding:10px 14px;margin-bottom:12px;font-size:1rem;
    font-variant-numeric:tabular-nums;overflow-x:auto;white-space:nowrap;
  }
  .eq b{color:var(--accent);}
  .controls{
    display:grid;grid-template-columns:1fr 1fr;gap:12px;
    background:var(--panel);border:1px solid var(--grid);
    border-radius:10px;padding:12px 14px;margin-bottom:12px;
  }
  @media (max-width:600px){ .controls{grid-template-columns:1fr;} }
  .ctrl{display:flex;flex-direction:column;gap:6px;}
  .ctrl label{font-size:.9rem;display:flex;justify-content:space-between;align-items:baseline;gap:8px;}
  .ctrl label b{color:var(--accent);font-variant-numeric:tabular-nums;}
  input[type=range]{width:100%;accent-color:var(--accent);cursor:pointer;height:22px;}
  input[type=range]:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:4px;}
  .two-col{
    display:grid;grid-template-columns:1.05fr 1fr;gap:12px;
  }
  @media (max-width:760px){ .two-col{grid-template-columns:1fr;} }
  .canvas-box{
    background:var(--panel);border:1px solid var(--grid);
    border-radius:10px;padding:8px;
  }
  canvas{display:block;width:100%;height:auto;border-radius:6px;}
  .legend{display:flex;flex-wrap:wrap;gap:14px;font-size:.78rem;color:var(--muted);margin-top:10px;}
  .legend span{display:flex;align-items:center;gap:6px;}
  .dot{width:11px;height:11px;border-radius:50%;display:inline-block;}
  .readout{
    display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));
    gap:8px;margin-top:12px;
  }
  .stat{background:var(--panel);border:1px solid var(--grid);border-radius:8px;padding:8px 10px;}
  .stat .k{color:var(--muted);font-size:.75rem;}
  .stat .v{font-size:1rem;font-weight:600;font-variant-numeric:tabular-nums;}
  .stat .v.accent{color:var(--accent);}
  .stat .v.op{color:var(--op);}
  .stat .v.hot{color:var(--hot);}
  .note{color:var(--muted);font-size:.78rem;margin-top:10px;}
</style>
</head>
<body>
<div class="wrap">
  <h1>欧姆定律：电压、电阻与电流</h1>
  <p class="sub">串联单回路，理想线性电阻：U = I·R，I = U/R，P = U·I</p>

  <div class="eq" id="eq"></div>

  <div class="controls">
    <div class="ctrl">
      <label for="volt">电压 U（V） <b><output id="voltOut">12.0</output></b></label>
      <input id="volt" type="range" min="0" max="24" step="0.5" value="12"
             aria-label="电压 U，范围 0 到 24 伏，步长 0.5">
    </div>
    <div class="ctrl">
      <label for="res">电阻 R（Ω） <b><output id="resOut">6.0</output></b></label>
      <input id="res" type="range" min="1" max="30" step="0.5" value="6"
             aria-label="电阻 R，范围 1 到 30 欧姆，步长 0.5">
    </div>
  </div>

  <div class="two-col">
    <div class="canvas-box">
      <canvas id="circuit" width="460" height="340" role="img"
              aria-label="串联电路图，显示电源、电阻和电流方向"></canvas>
    </div>
    <div class="canvas-box">
      <canvas id="plot" width="460" height="340" role="img"
              aria-label="电流随电压变化的直线，标出当前工作点"></canvas>
    </div>
  </div>

  <div class="legend" aria-hidden="true">
    <span><i class="dot" style="background:#7ee787"></i>导线与电流</span>
    <span><i class="dot" style="background:#ff8fa3"></i>电阻</span>
    <span><i class="dot" style="background:#4cc9f0"></i>当前工作点</span>
    <span><i class="dot" style="background:#ffd166"></i>电源</span>
  </div>

  <div class="readout">
    <div class="stat"><div class="k">电流 I = U/R</div><div class="v op" id="iOut">2.000 A</div></div>
    <div class="stat"><div class="k">电压 U</div><div class="v accent" id="uOut">12.0 V</div></div>
    <div class="stat"><div class="k">电阻 R</div><div class="v" id="rOut">6.0 Ω</div></div>
    <div class="stat"><div class="k">功率 P = U·I</div><div class="v hot" id="pOut">24.0 W</div></div>
    <div class="stat"><div class="k">每秒焦耳热 I²R</div><div class="v hot" id="heatOut">24.0 J/s</div></div>
    <div class="stat"><div class="k">电导 G = 1/R</div><div class="v" id="gOut">0.167 S</div></div>
  </div>

  <p class="note">电流大小以动画箭头流速与粗细表示；灯泡亮度随功率变化。I–U 图中直线斜率恒为 1/R，拖动电阻会改变斜率。</p>
</div>

<script>
(function(){
  "use strict";

  var circuit = document.getElementById("circuit");
  var cctx = circuit.getContext("2d");
  var plot = document.getElementById("plot");
  var pctx = plot.getContext("2d");

  var voltEl = document.getElementById("volt");
  var resEl = document.getElementById("res");
  var voltOut = document.getElementById("voltOut");
  var resOut = document.getElementById("resOut");
  var eqEl = document.getElementById("eq");
  var iOut = document.getElementById("iOut");
  var uOut = document.getElementById("uOut");
  var rOut = document.getElementById("rOut");
  var pOut = document.getElementById("pOut");
  var heatOut = document.getElementById("heatOut");
  var gOut = document.getElementById("gOut");

  function clamp(v, lo, hi){ return Math.min(hi, Math.max(lo, v)); }
  function num(v, d){ return (typeof v === "number" && isFinite(v)) ? v : d; }
  function fmt(v, d){
    var s = v.toFixed(d === undefined ? 2 : d);
    if (s === "-0.00") s = "0.00";
    return s;
  }

  var state = genui.getState() || {};
  var U = clamp(num(state.U, 12), 0, 24);
  var R = clamp(num(state.R, 6), 1, 30);
  voltEl.value = String(U);
  resEl.value = String(R);

  function saveState(){ genui.setState({ U: U, R: R }); }
  function current(){ return U / R; }
  function power(){ return U * current(); }

  function updateTexts(){
    voltOut.textContent = fmt(U, 1);
    resOut.textContent = fmt(R, 1);
    var I = current();
    var P = power();
    eqEl.innerHTML = "U = <b>" + fmt(U,1) + "</b> V，R = <b>" + fmt(R,1) + "</b> Ω &nbsp;⟹&nbsp; I = U/R = <b>" + fmt(I,3) + "</b> A";
    iOut.textContent = fmt(I, 3) + " A";
    uOut.textContent = fmt(U, 1) + " V";
    rOut.textContent = fmt(R, 1) + " Ω";
    pOut.textContent = fmt(P, 1) + " W";
    heatOut.textContent = fmt(P, 1) + " J/s";
    gOut.textContent = fmt(1 / R, 3) + " S";
  }

  // 电流动画相位（仅视觉）
  var phase = 0;
  var lastTs = 0;
  var rafId = null;

  function drawCircuit(){
    var W = circuit.width, H = circuit.height;
    cctx.clearRect(0, 0, W, H);
    cctx.fillStyle = "#101a24";
    cctx.fillRect(0, 0, W, H);

    var left = 70, right = W - 70, top = 70, bottom = H - 70;
    var I = current();

    // 导线
    cctx.strokeStyle = "#7ee787";
    cctx.lineWidth = 5;
    cctx.lineJoin = "round";
    cctx.beginPath();
    cctx.moveTo(left, top);
    cctx.lineTo(right, top);
    cctx.lineTo(right, bottom);
    cctx.lineTo(left, bottom);
    cctx.lineTo(left, top);
    cctx.stroke();

    // 电源（左侧竖边中段）
    var srcCy = (top + bottom) / 2;
    cctx.fillStyle = "#101a24";
    cctx.fillRect(left - 14, srcCy - 42, 28, 84);
    // 长线正极、短线负极
    cctx.strokeStyle = "#ffd166";
    cctx.lineWidth = 4;
    cctx.beginPath(); cctx.moveTo(left - 16, srcCy - 18); cctx.lineTo(left + 16, srcCy - 18); cctx.stroke();
    cctx.lineWidth = 6;
    cctx.beginPath(); cctx.moveTo(left - 9, srcCy + 16); cctx.lineTo(left + 9, srcCy + 16); cctx.stroke();
    cctx.fillStyle = "#ffd166";
    cctx.font = "12px system-ui, sans-serif";
    cctx.textAlign = "left"; cctx.textBaseline = "bottom";
    cctx.fillText("U = " + fmt(U,1) + " V", left + 22, srcCy - 22);
    cctx.textAlign = "center"; cctx.textBaseline = "top";
    cctx.fillText("+", left + 4, srcCy - 42);
    cctx.fillText("−", left - 4, srcCy + 24);

    // 电阻（上边中段）
    var resCx = (left + right) / 2;
    var rw = 78, rh = 32;
    cctx.fillStyle = "#101a24";
    cctx.fillRect(resCx - rw/2, top - rh/2, rw, rh);
    cctx.fillStyle = "#ff8fa3";
    cctx.strokeStyle = "#c96a80";
    cctx.lineWidth = 2;
    cctx.beginPath();
    if (cctx.roundRect) cctx.roundRect(resCx - rw/2, top - rh/2, rw, rh, 6);
    else cctx.rect(resCx - rw/2, top - rh/2, rw, rh);
    cctx.fill(); cctx.stroke();
    cctx.fillStyle = "#3a1420";
    cctx.font = "bold 13px system-ui, sans-serif";
    cctx.textAlign = "center"; cctx.textBaseline = "middle";
    cctx.fillText("R = " + fmt(R,1) + " Ω", resCx, top);

    // 电流方向箭头（沿导线移动）
    if (I > 1e-9){
      var speed = clamp(20 + I * 45, 30, 220); // 像素/秒
      var perimeter = 2 * (right - left) + 2 * (bottom - top);
      var offset = (phase * speed) % perimeter;
      var nArrows = 8;
      for (var a = 0; a < nArrows; a++){
        var d = (offset + (a / nArrows) * perimeter) % perimeter;
        var p = pointOnPerimeter(d, left, right, top, bottom);
        if (p.skip) continue;
        drawArrow(p.x, p.y, p.ang, Math.min(0.5 + I * 0.25, 1));
      }
    }

    // 电流表读数
    cctx.fillStyle = "#4cc9f0";
    cctx.font = "bold 14px system-ui, sans-serif";
    cctx.textAlign = "center"; cctx.textBaseline = "middle";
    cctx.fillText("I = " + fmt(I, 3) + " A", (left + right) / 2, bottom - 24);

    function pointOnPerimeter(d, l, r, t, b){
      var w = r - l, h = b - t;
      // 从上边中点开始顺时针：上边 → 右边 → 下边 → 左边
      var cx = (l + r) / 2;
      var seg;
      // 上边右半段 + 右边 + 下边 + 左边 + 上边左半段
      var total = w + h + w + h;
      d = ((d % total) + total) % total;
      if (d < w / 2 + (r - cx)){ // 上边（从中心向右）
        var x = cx + d;
        if (x > r){ var over = x - r; return { x: r, y: t + over, ang: Math.PI/2 }; }
        return { x: x, y: t, ang: 0 };
      }
      var d2 = d - (w / 2 + (r - cx));
      if (d2 < h){
        return { x: r, y: t + d2, ang: Math.PI/2 };
      }
      d2 -= h;
      if (d2 < w){
        return { x: r - d2, y: b, ang: Math.PI };
      }
      d2 -= w;
      if (d2 < h){
        // 左侧经过电源时跳过箭头
        var y = b - d2;
        if (Math.abs(y - srcCy) < 50) return { skip: true };
        return { x: l, y: y, ang: -Math.PI/2 };
      }
      d2 -= h;
      // 上边左半段
      var x2 = l + d2;
      if (Math.abs(x2 - resCx) < 50) return { skip: true };
      return { x: x2, y: t, ang: 0 };
    }

    function drawArrow(x, y, ang, alpha){
      cctx.save();
      cctx.translate(x, y);
      cctx.rotate(ang);
      cctx.globalAlpha = alpha;
      cctx.fillStyle = "#7ee787";
      cctx.beginPath();
      cctx.moveTo(7, 0);
      cctx.lineTo(-5, -5);
      cctx.lineTo(-5, 5);
      cctx.closePath();
      cctx.fill();
      cctx.restore();
    }
  }

  function drawPlot(){
    var W = plot.width, H = plot.height;
    var padL = 56, padR = 20, padT = 22, padB = 46;
    var plotW = W - padL - padR;
    var plotH = H - padT - padB;

    pctx.clearRect(0, 0, W, H);
    pctx.fillStyle = "#101a24";
    pctx.fillRect(padL, padT, plotW, plotH);

    var Umax = 24;
    // 纵轴按当前电阻下的最大电流留余量，但至少 1A
    var Imax = Math.max(Umax / R * 1.1, 1);

    function xOf(u){ return padL + (u / Umax) * plotW; }
    function yOf(i){ return padT + plotH - (i / Imax) * plotH; }

    // 网格
    pctx.strokeStyle = "#26364a";
    pctx.lineWidth = 1;
    pctx.fillStyle = "#9fb0c0";
    pctx.font = "11px system-ui, sans-serif";
    pctx.textAlign = "center"; pctx.textBaseline = "top";
    for (var gu = 0; gu <= Umax; gu += 4){
      var px = xOf(gu);
      pctx.beginPath(); pctx.moveTo(px, padT); pctx.lineTo(px, padT + plotH); pctx.stroke();
      pctx.fillText(String(gu), px, padT + plotH + 6);
    }
    pctx.textAlign = "right"; pctx.textBaseline = "middle";
    var iStep = niceStep(Imax / 5);
    for (var gi = 0; gi <= Imax + 1e-9; gi += iStep){
      var py = yOf(gi);
      if (py < padT - 0.5) break;
      pctx.beginPath(); pctx.moveTo(padL, py); pctx.lineTo(padL + plotW, py); pctx.stroke();
      pctx.fillText(fmt(gi, 1), padL - 6, py);
    }

    // 坐标轴
    pctx.strokeStyle = "#55708a";
    pctx.lineWidth = 1.6;
    pctx.beginPath(); pctx.moveTo(padL, yOf(0)); pctx.lineTo(padL + plotW, yOf(0)); pctx.stroke();
    pctx.beginPath(); pctx.moveTo(xOf(0), padT); pctx.lineTo(xOf(0), padT + plotH); pctx.stroke();

    pctx.fillStyle = "#9fb0c0";
    pctx.font = "12px system-ui, sans-serif";
    pctx.textAlign = "right"; pctx.textBaseline = "bottom";
    pctx.fillText("U (V)", padL + plotW, yOf(0) - 5);
    pctx.textAlign = "left"; pctx.textBaseline = "top";
    pctx.fillText("I (A)", xOf(0) + 6, padT - 2);

    // I-U 直线：I = U/R，画到 Imax 对应的电压
    var uLineMax = Math.min(Umax, Imax * R);
    pctx.beginPath();
    pctx.moveTo(xOf(0), yOf(0));
    pctx.lineTo(xOf(uLineMax), yOf(uLineMax / R));
    pctx.strokeStyle = "#ff8fa3";
    pctx.lineWidth = 2.4;
    pctx.lineCap = "round";
    pctx.stroke();

    // 斜率标注
    pctx.fillStyle = "#ff8fa3";
    pctx.font = "11px system-ui, sans-serif";
    pctx.textAlign = "left"; pctx.textBaseline = "bottom";
    var lx = xOf(uLineMax * 0.62), ly = yOf(uLineMax * 0.62 / R);
    pctx.fillText("斜率 = 1/R = " + fmt(1/R, 3) + " S", lx + 6, ly - 6);

    // 当前工作点
    var I = current();
    var opx = xOf(clamp(U, 0, Umax));
    var opy = yOf(clamp(I, 0, Imax));
    pctx.save();
    pctx.setLineDash([4, 4]);
    pctx.strokeStyle = "rgba(76,201,240,0.55)";
    pctx.lineWidth = 1.3;
    pctx.beginPath(); pctx.moveTo(opx, yOf(0)); pctx.lineTo(opx, opy); pctx.stroke();
    pctx.beginPath(); pctx.moveTo(padL, opy); pctx.lineTo(opx, opy); pctx.stroke();
    pctx.restore();

    pctx.fillStyle = "#4cc9f0";
    pctx.beginPath(); pctx.arc(opx, opy, 6, 0, Math.PI*2); pctx.fill();
    pctx.strokeStyle = "#0f1720"; pctx.lineWidth = 2; pctx.stroke();
    pctx.fillStyle = "#4cc9f0";
    pctx.font = "bold 11px system-ui, sans-serif";
    pctx.textAlign = "left"; pctx.textBaseline = "bottom";
    pctx.fillText("(" + fmt(U,1) + "V, " + fmt(I,2) + "A)", opx + 9, opy - 8);
  }

  function niceStep(raw){
    if (raw <= 0) return 1;
    var mag = Math.pow(10, Math.floor(Math.log10(raw)));
    var n = raw / mag;
    var step;
    if (n <= 1) step = 1;
    else if (n <= 2) step = 2;
    else if (n <= 5) step = 5;
    else step = 10;
    return step * mag;
  }

  function frame(ts){
    if (!lastTs) lastTs = ts;
    var dt = (ts - lastTs) / 1000;
    lastTs = ts;
    phase += dt;
    drawCircuit();
    rafId = requestAnimationFrame(frame);
  }

  function refresh(){
    updateTexts();
    drawCircuit();
    drawPlot();
  }

  voltEl.addEventListener("input", function(){
    U = clamp(parseFloat(voltEl.value) || 0, 0, 24);
    saveState(); refresh();
  });
  resEl.addEventListener("input", function(){
    R = clamp(parseFloat(resEl.value) || 1, 1, 30);
    saveState(); refresh();
  });

  saveState();
  refresh();
  rafId = requestAnimationFrame(frame);
})();
</script>
</body>
